type EpochMillis = number & { readonly __brand: 'EpochMillis' };
interface Expiring<T> { payload: T; expiresAt: EpochMillis }

const isStale = <T>(m: Expiring<T>): boolean => Date.now() >= m.expiresAt;

const msg: Expiring<Order> = { payload: order, expiresAt: (Date.now() + 60_000) as EpochMillis };
if (!isStale(msg)) {
  await request(url, { signal: AbortSignal.timeout(msg.expiresAt - Date.now()) });
} else {
  deadLetter(msg);
}

